```python
from typing import Literal


class AnotherMixin: ...


class Mixin:
    def __init_subclass__(cls) -> None:
        cls.kwargs: dict[Literal["init"], bool] = {"init": False} if issubclass(cls, AnotherMixin) else {}
```

