        self.item = obj

class Container[D: Dumpable](BaseContainer[D]):
    def __init__(self, obj: D) -> None:
        self.item = obj


def foo[S: Dumpable](obj: BaseContainer[S]) -> S:
    return obj.item

foo(Container("test"))
